/* eslint-disable react/no-unescaped-entities */
"use client"
import React, { useRef } from 'react';
import { Button } from '@/components/ui/button';
import { HiCode, HiArrowRight } from 'react-icons/hi';
import { config } from '@/config';
import Link from 'next/link';
import { BackgroundPresets } from '@/components/ui/background-effects';
import { motion } from 'framer-motion';
import SkillsShowcase from './SkillsShowcase';
import VariableProximity from '@/components/ui/VariableProximity';
import PixelSnow from '@/components/ui/PixelSnow';
import StarBorder from '@/components/ui/StarBorder';

const containerAnimation = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: {
      staggerChildren: 0.2,
      delayChildren: 0.3
    }
  }
};

const itemAnimation = {
  hidden: { opacity: 0, y: 20 },
  show: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.5,
      ease: "easeOut"
    }
  }
};

const textAnimation = {
  hidden: { opacity: 0, x: -20 },
  show: {
    opacity: 1,
    x: 0,
    transition: {
      duration: 0.5,
      ease: "easeOut"
    }
  }
};

const HeroSection = () => {
  const containerRef = useRef(null);
  return (
    <section className="min-h-[calc(100vh-140px)] flex items-center justify-center relative overflow-hidden">
      <div className="absolute inset-0 z-0">
        <PixelSnow
          color="#ffffff"
          flakeSize={0.008} // Smaller flakes for "thin snow" look
          pixelResolution={450} // Higher resolution for sharper, less blurry pixels
          speed={1.5}
          density={0.2}
          direction={135}
          className="w-full h-full"
        />
      </div>
      <BackgroundPresets.Minimal />

      <div className="container mx-auto px-6">
        <motion.div
          ref={containerRef}
          variants={containerAnimation}
          initial="hidden"
          animate="show"
          className="max-w-3xl mx-auto text-center space-y-8 relative mt-16 sm:mt-24"
        >

          <motion.div
            variants={itemAnimation}
          >
            <StarBorder
              as="div"
              className="inline-flex items-center space-x-2 bg-secondary/10 px-4 py-2 rounded-full text-primary backdrop-blur-sm"
              color="white"
              speed="6s"
            >
              <HiCode className="w-5 h-5" />
              <span className="text-sm font-medium">Welcome to my portfolio</span>
            </StarBorder>
          </motion.div>

          <div className="space-y-4">
            <motion.h1
              variants={itemAnimation}
              className="text-4xl md:text-7xl font-bold tracking-tight"
            >
              <motion.span
                variants={textAnimation}
                className="block text-primary mb-2"
              >
                <VariableProximity
                  label={`Hi, I'm ${config.developer.name}`}
                  className="cursor-pointer tracking-tight"
                  fromFontVariationSettings="'wght' 700, 'opsz' 9"
                  toFontVariationSettings="'wght' 900, 'opsz' 40"
                  containerRef={containerRef}
                  radius={100}
                  falloff="linear"
                />
              </motion.span>
              <motion.span
                variants={textAnimation}
                className="block text-white/60 text-2xl md:text-4xl"
              >
                <VariableProximity
                  label="I Am Proficient in UI/UX, Design, and Frontend Development."
                  className="cursor-pointer tracking-tight"
                  fromFontVariationSettings="'wght' 400, 'opsz' 9"
                  toFontVariationSettings="'wght' 700, 'opsz' 40"
                  containerRef={containerRef}
                  radius={100}
                  falloff="linear"
                />
              </motion.span>
            </motion.h1>
          </div>

          <motion.p
            variants={itemAnimation}
            className="text-base sm:text-md text-muted-foreground leading-relaxed max-w-2xl mx-auto"
          >
            I specialize in UI/UX Design, Frontend Development, and Graphic Design. Driven by collaboration and social activity, my goal is to deliver impactful digital solutions through professional projects and continuous growth.
          </motion.p>

          <motion.div
            variants={itemAnimation}
            className="flex flex-wrap gap-4 justify-center pt-6"
          >
            <Link href={"/projects"}>
              <Button
                variant="expandIcon"
                Icon={HiArrowRight}
                iconPlacement="right"
                className="rounded-full px-6 py-6 text-base transition-all duration-300 hover:scale-105 font-semibold"
              >
                View Projects
              </Button>
            </Link>
          </motion.div>



          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1, duration: 1 }}
            className="absolute -z-10 inset-0 pointer-events-none"
          >
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-primary/5 rounded-full blur-3xl" />
          </motion.div>
        </motion.div>
        <SkillsShowcase />
      </div>
    </section>
  );
};

export default HeroSection;